</SidebarGroup>

import Avatar from "../../components/ui/avatar/avatar.marko";
import DropdownMenu from "../../components/ui/dropdown-menu/dropdown-menu.marko";
import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";

export interface NavUserData {
  name: string;
  email: string;
  avatar: string;
}

export interface Input {
  user: NavUserData;
}

// The dropdown-menu `<@item>` attr tag accepts a markup `content` body plus
// a `class` override on label entries (see
// ui/dropdown-menu/dropdown-menu.marko), so the source's rich
// DropdownMenuLabel — avatar + name/email, with `p-0 font-normal` replacing
// the default padded/muted label classes — ports faithfully instead of
// being flattened to a plain string label.
//
// Width: the source sizes DropdownMenuContent with
// `w-(--radix-dropdown-menu-trigger-width)`, a Radix CSS var mirroring the
// trigger's measured width. zag's popper exposes the same measurement as
// `--reference-width` on the positioner (see @zag-js/popper
// get-placement.js/get-styles.js), so `w-(--reference-width)` is the
// visual-equivalent mapping for our primitive.

<SidebarMenu>
  <SidebarMenuItem>
    <DropdownMenu class="w-(--reference-width) min-w-56 rounded-lg">
      <@trigger|triggerProps|>
        <SidebarMenuButton
          ...triggerProps
          size="lg"
          class="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground"
        >
          <Avatar src=input.user.avatar alt=input.user.name fallback="CN" class="h-8 w-8 rounded-lg"/>
          <div class="grid flex-1 text-left text-sm leading-tight">
            <span class="truncate font-medium">${input.user.name}</span>
            <span class="truncate text-xs">${input.user.email}</span>
          </div>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class="ml-auto size-4"
          >
            <path d="m7 15 5 5 5-5"/>
            <path d="m7 9 5-5 5 5"/>
          </svg>
        </SidebarMenuButton>
      </@trigger>
      <@item type="label" class="p-0 font-normal">
        <div class="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
          <Avatar src=input.user.avatar alt=input.user.name fallback="CN" class="h-8 w-8 rounded-lg"/>
          <div class="grid flex-1 text-left text-sm leading-tight">
            <span class="truncate font-medium">${input.user.name}</span>
            <span class="truncate text-xs">${input.user.email}</span>
          </div>
        </div>
      </@item>
      <@item type="separator"/>
      <@item type="item" value="upgrade" label="Upgrade to Pro"/>
      <@item type="separator"/>
      <@item type="item" value="account" label="Account"/>
      <@item type="item" value="billing" label="Billing"/>
      <@item type="item" value="notifications" label="Notifications"/>
      <@item type="separator"/>
      <@item type="item" value="logout" label="Log out"/>
    </DropdownMenu>
  </SidebarMenuItem>
</SidebarMenu>

import SidebarProvider from "../../components/ui/sidebar/provider.marko";
import SidebarTrigger from "../../components/ui/sidebar/trigger.marko";
import Separator from "../../components/ui/separator/separator.marko";
import Breadcrumb from "../../components/ui/breadcrumb/breadcrumb.marko";
import BreadcrumbItem from "../../components/ui/breadcrumb/item.marko";
import BreadcrumbPage from "../../components/ui/breadcrumb/page.marko";
import SidebarLeft from "./sidebar-left.marko";
import SidebarRight from "./sidebar-right.marko";

// NOTE: shadcn's SidebarInset (a <main> variant that insets/rounds the
// content area) has no dedicated equivalent among our sidebar sub-parts,
// so the content region is a plain flex <div>, matching the precedent in
// blocks/dashboard-01/page.marko and blocks/sidebar-07/page.marko.
//
// The right sidebar is `collapsible="none"` in the source (always
// visible on desktop, independent of the provider's open/toggle state),
// so it is rendered as a sibling inside `@content` rather than through
// the provider's single `@sidebar` slot, which only supports one panel.

<SidebarProvider width="16rem">
  <@sidebar|{ open }|>
    <SidebarLeft open=open/>
  </@sidebar>
  <@content|{ open, toggle }|>
    <div class="flex min-w-0 flex-1">
      <div class="flex min-w-0 flex-1 flex-col">
        <header class="sticky top-0 flex h-14 shrink-0 items-center gap-2 bg-background">
          <div class="flex flex-1 items-center gap-2 px-3">
            <SidebarTrigger open=open toggle=toggle/>
            <Separator orientation="vertical" class="mr-2 h-4"/>
            <Breadcrumb>
              <BreadcrumbItem>
                <BreadcrumbPage class="line-clamp-1">Project Management & Task Tracking</BreadcrumbPage>
              </BreadcrumbItem>
            </Breadcrumb>
          </div>
        </header>
        <div class="flex flex-1 flex-col gap-4 p-4">
          <div class="mx-auto h-24 w-full max-w-3xl rounded-xl bg-muted/50"></div>
          <div class="mx-auto h-[100vh] w-full max-w-3xl rounded-xl bg-muted/50"></div>
        </div>
      </div>
      <SidebarRight/>
    </div>
  </@content>
</SidebarProvider>

