import SidebarMenu from "../../components/ui/sidebar/menu.marko";
import SidebarMenuItem from "../../components/ui/sidebar/menu-item.marko";
import SidebarMenuButton from "../../components/ui/sidebar/menu-button.marko";
import DropdownMenu from "../../components/ui/dropdown-menu/dropdown-menu.marko";

export interface Team {
  id: string;
  name: string;
  plan: string;
  /** SVG path `d` attribute(s) for a 24x24 lucide-style icon, rendered inline. */
  logo: string;
}

export interface Input {
  teams: Team[];
}

// NOTE: our DropdownMenu items are a flat data list (type: item | separator
// | label) with a single `label` string, so the source's per-team logo icon
// inside each menu row and the ⌘N keyboard-shortcut hint have no equivalent
// slot to render into. Both are dropped here, following the precedent set
// in blocks/sidebar-07/team-switcher.marko. Deviation from the source,
// noted per block-porting rules.

<let/activeTeamId=input.teams[0]?.id/>
<const/activeTeam=input.teams.find((team) => team.id === activeTeamId) ?? input.teams[0]/>

<const/menuItems=[
  { type: "label" as const, label: "Teams" },
  ...input.teams.map((team) => ({ type: "item" as const, value: team.id, label: team.name })),
  { type: "separator" as const },
  { type: "item" as const, value: "add-team", label: "Add team" },
]/>

<if=activeTeam>
  <SidebarMenu>
    <SidebarMenuItem>
      <DropdownMenu
        items=menuItems
        class="w-64 rounded-lg"
        select(value: string) {
          if (value !== "add-team") activeTeamId = value;
        }
      >
        <@trigger|triggerProps|>
          <SidebarMenuButton ...triggerProps class="w-fit px-1.5">
            <div
              class="flex aspect-square size-5 items-center justify-center rounded-md bg-sidebar-primary text-sidebar-primary-foreground"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
                class="size-3"
              >
                <path d=activeTeam.logo/>
              </svg>
            </div>
            <span class="truncate font-medium">${activeTeam.name}</span>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
              class="opacity-50"
            >
              <path d="m6 9 6 6 6-6"/>
            </svg>
          </SidebarMenuButton>
        </@trigger>
      </DropdownMenu>
    </SidebarMenuItem>
  </SidebarMenu>
</if>
